contract InvMutTest {
    C c;
    bytes4 constant SEL_PFD = 0x11111111;

    constructor(C _c) {
        c = _c;
        SEL_PFD = bytes4(keccak256("protocolFeeDestination()"));
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length >= 4 && bytes4(data) == SEL_PFD) {
            return abi.encode(address(0x1));
        }
        return abi.encode(uint256(0));
    }

    receive() external payable {}

    function run(uint256 artId, uint256 value) public payable {
        require(address(this).balance >= value);
        c.initialize(1, 1, "v", address(0x1));
        uint256 before = c.tokenIdCounter();
        uint256 tid = c.createArtFromFactory{value: value}(artId);
        assert(
            tid == before
                && tid >= 1
                && c.getTokenIdFromFactoryArtId(artId) == tid
                && c.getFactoryArtId(tid) == artId
                && c.tokenIdCounter() == tid + 1
        );
    }
}

