contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // c views this contract as its phiFactory; artCreateFee() -> 0, protocolFeeDestination() -> this
        if (msg.sig == bytes4(keccak256("protocolFeeDestination()"))) {
            return abi.encode(address(this));
        }
        return abi.encode(uint256(0));
    }

    receive() external payable {}

    function run(uint256 artId) public {
        require(artId > 0);
        require(artId < 1000000);
        c.initialize(1, 1, "v", address(this));
        uint256 tidBefore = c.tokenIdCounter();
        uint256 tid = c.createArtFromFactory{value: 0}(artId);
        assert(c.getTokenIdFromFactoryArtId(artId) == tid && tid == tidBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 artIdA, uint256 artIdB, uint256 amount) public payable {
        require(artIdA != artIdB);
        c.initialize(1, 1, "v", address(this));
        uint256 before = c.tokenIdCounter();
        uint256 t1 = c.createArtFromFactory{value: amount}(artIdA);
        uint256 t2 = c.createArtFromFactory{value: amount}(artIdB);
        assert(
            c.getTokenIdFromFactoryArtId(artIdA) == t1 &&
            c.getTokenIdFromFactoryArtId(artIdB) == t2 &&
            c.getFactoryArtId(t1) == artIdA &&
            c.getFactoryArtId(t2) == artIdB &&
            t1 != t2 &&
            c.tokenIdCounter() == before + 2
        );
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        if (msg.sig == bytes4(keccak256("protocolFeeDestination()"))) {
            return abi.encode(address(this));
        }
        return abi.encode(uint256(0));
    }

    receive() external payable {}
}

