contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address feeDest, uint256 artId) public {
        c.initialize(1, 1, "v", feeDest);
        c.pause();
        bool reverted;
        try c.createArtFromFactory(artId) { reverted = false; }
        catch { reverted = true; }
        bool pausedNow = c.paused();
        c.unPause();
        assert(pausedNow && reverted && !c.paused());
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address outsider) public {
        c.initialize(1, 1, "v", address(this));
        address ownerBefore = c.owner();
        c.transferOwnership(newOwner);
        address pendingNow = c.pendingOwner();
        address ownerMid = c.owner();
        // outsider tries to accept ownership
        bool reverted;
        try c.acceptOwnership() { reverted = false; }
        catch { reverted = true; }
        assert(
            newOwner != address(0)
            && ownerBefore != newOwner
            && pendingNow == newOwner
            && ownerMid == ownerBefore
            && reverted
            && c.owner() == ownerBefore
            && c.pendingOwner() == newOwner
        );
    }

    receive() external payable {}
}
